(function(){'use strict';const M=DecideCharacterModel;let appearance=M.validate(),pose='idle',facing=0,lastGender='',account='';const box=document.createElement('article');box.id='characterCustomizer';box.innerHTML='<h2>ประกอบตัวละครต่อสู้</h2><p>เลือกใบหน้าและผม • ชุดและอาวุธเปลี่ยนตามอุปกรณ์ที่สวม</p><div style="display:flex;flex-wrap:wrap;gap:24px"><canvas id="modelPreview" width="360" height="360" style="width: min(100%,360px);height:auto;background:radial-gradient(#355d63,#112e32);border-radius:18px" aria-label="ตัวอย่างตัวละครเคลื่อนไหว"></canvas><div id="modelOptions" style="flex:1;min-width:200px"></div></div><div id="modelPoses" class="skills"></div><button type="button" id="modelTurn">หมุนดูอีกด้าน</button>';$('creationSummary').before(box);
const options=$('modelOptions');for(const [key,values]of Object.entries(M.choices)){const label=document.createElement('label');label.style.display='block';label.style.marginBottom='14px';label.textContent={body:'รูปร่าง',face:'ใบหน้า',hair:'ทรงผม',hairColor:'สีผม',skin:'สีผิว'}[key];const select=document.createElement('select');select.dataset.model=key;for(const [id,name]of Object.entries(values))select.add(new Option(name,id));select.value=appearance[key];select.onchange=()=>{appearance[key]=select.value;persist();};label.append(select);options.append(label);}
for(const [id,name]of Object.entries({idle:'ยืน',walk:'เดิน',attack:'โจมตี',cast:'ร่ายเวท',guard:'ตั้งรับ',hit:'โดนโจมตี',down:'ล้ม'})){const b=document.createElement('button');b.type='button';b.textContent=name;b.onclick=()=>pose=id;$('modelPoses').append(b);}$('modelTurn').onclick=()=>facing=(facing+1)%4;
function persist(){if(!storageKey)return;try{const d=JSON.parse(localStorage.getItem(storageKey+':creation-draft')||'null');if(d){d.appearance=appearance;localStorage.setItem(storageKey+':creation-draft',JSON.stringify(d));}localStorage.setItem(storageKey+':appearance',JSON.stringify(appearance));}catch{}}
function controls(){for(const el of options.querySelectorAll('select'))el.value=appearance[el.dataset.model];}
const canvas=$('modelPreview'),ctx=canvas.getContext('2d');function loop(t){if(screen==='createScreen'&&uid&&!document.hidden){if(account!==uid){account=uid;try{appearance=M.validate(JSON.parse(localStorage.getItem(storageKey+':appearance')||'null'));}catch{appearance=M.validate();}controls();lastGender='';}const gender=document.querySelector('[name=gender]:checked')?.value;if(gender!==lastGender){lastGender=gender;if(['male','female'].includes(gender)){appearance.body=gender;controls();persist();}}const job=document.querySelector('[name=job]:checked')?.value||'warrior',race=document.querySelector('[name=race]:checked')?.value||'human',weapon=$('starterWeapon')?.value||DecideCreation.classes[job].starter[0];ctx.clearRect(0,0,360,360);ctx.fillStyle='#142b3355';ctx.beginPath();ctx.ellipse(180,315,65,20,0,0,Math.PI*2);ctx.fill();M.draw(ctx,180,310,235,appearance,{main:DecideCreation.weapons[weapon].type,off:job==='knight'?'shield':null,armor:DecideCreation.classes[job].armor},pose,t,facing,race);}requestAnimationFrame(loop);}requestAnimationFrame(loop);window.DecideCustomizer={value:()=>M.validate(appearance)};
})();
